-- Run in the database/schema configured for Klane. No sample data is inserted.
CREATE TABLE IF NOT EXISTS KLANE_SIGNAL_EVENTS(ACCOUNT_ID VARCHAR, EVENT_ID VARCHAR, SIGNAL_ID VARCHAR, COMPANY_ID VARCHAR, OBSERVED_AT TIMESTAMP_TZ, COLLECTED_AT TIMESTAMP_TZ, CITY VARCHAR, SERVICE VARCHAR, KIND VARCHAR, STATUS VARCHAR, CONFIDENCE FLOAT, SOURCE_URL VARCHAR);
CREATE TABLE IF NOT EXISTS KLANE_JOB_COMPARABLES(JOB_ID VARCHAR, CITY VARCHAR, SERVICE VARCHAR, UNIT VARCHAR, SCOPE_CLASS VARCHAR, COMPLETED_AT DATE, UNITS FLOAT, CONTRACT_VALUE FLOAT, DIRECT_COST FLOAT, SOURCE_URL VARCHAR, VERIFIED BOOLEAN);
-- Comparable records must match trade, units, scope class and locality.
-- Ingest actual completed-project/award records; do not seed fabricated market rates.

CREATE TABLE IF NOT EXISTS KLANE_PERMIT_REFERENCE (RECORD_ID VARCHAR,CITY VARCHAR,SERVICES VARIANT,ISSUED_AT DATE,DESCRIPTION VARCHAR,ADDRESS VARCHAR,WORK_CLASS VARCHAR,PROPERTY_CLASS VARCHAR,STATUS VARCHAR,DECLARED_VALUE FLOAT,SOURCE_URL VARCHAR,FETCHED_AT TIMESTAMP_TZ);
